const GROUPS=[
  {id:'paper-1a',title:'Paper I-A · Political theory and thought',prefix:'1A-',books:'Books 2–6'},
  {id:'paper-1b',title:'Paper I-B · Indian government and politics',prefix:'1B-',books:'Books 7–9'},
  {id:'paper-2a',title:'Paper II-A · Comparative politics and international relations',prefix:'2A-',books:'Books 10–13'},
  {id:'paper-2b',title:'Paper II-B · India and the world',prefix:'2B-',books:'Books 14–17'}
];
const esc=value=>String(value).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const byTopic=QUESTION_DATA.questions.reduce((map,row)=>{(map[row.topic]??=[]).push(row);return map;},{});
const orderedRows=rows=>[...rows].sort((a,b)=>b.year-a.year||a.paper.localeCompare(b.paper)||a.code.localeCompare(b.code,undefined,{numeric:true}));
const questionRow=row=>`<li class="pyq-question"><span class="pyq-code">${row.year} · P${row.paper} · Q${row.code} · ${row.marks}m</span><span>${esc(row.question)}</span></li>`;
const topicCard=(id,index)=>{
  const rows=orderedRows(byTopic[id]||[]);
  const label=QUESTION_DATA.topics[id];
  return `<details class="pyq-topic"${index===0?' open':''}><summary><span>${esc(label)}</span><b>${rows.length} questions</b></summary><p class="pyq-topic-note">Read the newest prompts first. Then write one short and one long answer from different years before reopening the list.</p><ol class="pyq-question-list">${rows.map(questionRow).join('')}</ol></details>`;
};
const clusterSection=group=>{
  const ids=Object.keys(QUESTION_DATA.topics).filter(id=>id.startsWith(group.prefix));
  const count=ids.reduce((total,id)=>total+(byTopic[id]||[]).length,0);
  return {id:group.id,title:group.title,html:`<p>This map follows the official syllabus headings covered mainly in ${group.books}. It contains <b>${count}</b> individually addressable prompts from the 2013–2025 papers. A question may touch more than one debate; it is stored under the topic that should lead your answer.</p><div class="pyq-topic-bank">${ids.map(topicCard).join('')}</div>`};
};
const yearRows=Array.from({length:13},(_,index)=>2025-index).map(year=>{
  const paperOne=QUESTION_DATA.questions.filter(row=>row.year===year&&row.paper==='I').length;
  const paperTwo=QUESTION_DATA.questions.filter(row=>row.year===year&&row.paper==='II').length;
  return `<tr><td>${year}</td><td>${paperOne}</td><td>${paperTwo}</td><td>${paperOne+paperTwo}</td></tr>`;
}).join('');
const sections=[
  {id:'how-to-use',title:'What this book contains and how to use it',html:`<p>This is a searchable, topic-wise bank of <b>728 individually addressable PSIR Mains prompts</b> from 2013–2025: 28 question parts in each Paper I and Paper II paper. It is a practice index, not a set of model answers. The question text is lightly normalised for line breaks, punctuation and obvious scan errors; use the linked UPSC paper when exact wording matters.</p><div class="concept-frame"><h3>Use each topic in three passes</h3><ol><li><b>Scan:</b> read every prompt and mark the directive—comment, explain, examine, discuss, analyse, compare or evaluate.</li><li><b>Map:</b> make a one-page answer asset list: concepts, thinkers, cases, counter-arguments and current evidence.</li><li><b>Write:</b> choose one 10-marker and one 15/20-marker from different years. Check the official PDF before timing a full answer.</li></ol></div><table><tr><th>Code</th><th>Meaning</th><th>How to use it</th></tr><tr><td>2024 · P II · Q7b · 15m</td><td>Year, paper, printed question-part and marks.</td><td>Find it quickly in the original paper and plan time proportionately.</td></tr><tr><td>Topic heading</td><td>The main syllabus home chosen for revision.</td><td>Add a second tag in your notebook where the question is genuinely cross-topic.</td></tr><tr><td>Question count</td><td>Number of individually answerable prompts, including short compulsory parts.</td><td>Use it to judge revision load, not to predict the next paper.</td></tr></table><p>Do not treat recurrence as a forecast. UPSC often changes the proposition, directive, case or scale while testing a familiar conceptual family.</p>`},
  ...GROUPS.map(clusterSection),
  {id:'coverage-audit',title:'Coverage audit: every year and both papers',html:`<p>Each annual row has 56 answerable components: 28 in Paper I and 28 in Paper II. This audit helps you check that you have worked across the whole period rather than over-practising only recent papers.</p><table><tr><th>Year</th><th>Paper I</th><th>Paper II</th><th>Total prompts</th></tr>${yearRows}</table><div class="revision-grid"><div><b>2013–2014</b>Read the archive transcription with the official UPSC archive page open. The current UPSC listing does not expose a downloadable 2013 PSIR PDF, and several older official files are scanned images.</div><div><b>2015–2025</b>Use the official yearly PDFs for exact wording, time limits and any qualification in the question.</div><div><b>Topic tag</b>Each prompt has one primary tag to keep revision practical. Use the prompt itself—not the tag alone—to select relevant thinkers and evidence.</div><div><b>Answer record</b>After an attempt, record thesis quality, missing anchor, missing counter, evidence accuracy and time loss. Re-attempt only after repair.</div></div>`}
];
PSIR.build({id:'20',title:'Topic-Wise UPSC Mains Questions (2013–2025)',kicker:'Book 20 · Complete PSIR PYQ bank',dek:'All 728 answerable question parts from the 2013–2025 PSIR Mains papers, grouped under the official syllabus topics for targeted practice.',prev:'19-answer-writing-manual.html',objectives:['Locate every 2013–2025 PSIR Mains prompt under one practical primary syllabus topic.','Recognise the difference between a question topic, directive and hidden cross-topic demand.','Plan topic-wise answer practice across 10-, 15- and 20-mark questions.','Verify exact wording, marks and paper structure from the linked UPSC record before a timed attempt.'],syllabus:'The bank covers the full PSIR Optional syllabus: Paper I-A, Paper I-B, Paper II-A and Paper II-B. It keeps Paper I and Paper II identifiers visible on every entry even when a prompt requires a cross-paper concept or case.',sections,prompts:[{q:'“Repeated PSIR questions test recurring intellectual problems, not identical answers.” Discuss with examples from any one topic family.',demand:'Explain recurrence without claiming that an exact question will repeat.',thesis:'Repeated prompts reveal durable conceptual tensions, but a usable answer must respond to the changing directive, context and counter-argument in the new formulation.',points:['Identify the underlying question family.','Show how directive and scope alter the answer contract.','Use a comparison of two prompts from different years.','Conclude with a reusable, but adaptable, answer asset.'],close:'Preparation should build conceptual flexibility rather than memorised reproductions.'},{q:'How should a candidate turn a 10-mark PYQ and a 20-mark PYQ from the same topic into two different answers?',demand:'Set out a practical difference in depth, selection and time.',thesis:'The short answer needs a precise definition, one mechanism, two anchors and a qualified close; the longer answer must add a debate, developed reasoning, counter-view and sharper judgement.',points:['Read the directive and mark the task.','Select only the material that proves the thesis.','Scale paragraph count and evidence to marks.','Preserve a conclusion in both answers.'],close:'More marks require deeper reasoning, not a longer catalogue of facts.'},{q:'Why should a multi-topic PSIR question be filed under one primary topic in a revision system?',demand:'Defend or qualify the use of a primary tag.',thesis:'A primary tag makes retrieval and practice possible, while a visible secondary bridge prevents artificial compartmentalisation of the syllabus.',points:['Explain the value of a retrieval home.','Identify the hidden bridge in the question.','Show how thinkers, institutions or cases travel across papers.','Warn against treating a tag as a complete answer.'],close:'Good filing serves answer construction; it does not replace it.'},{q:'Design a four-week topic-wise PYQ cycle using this bank.',demand:'Give a feasible sequence with written outputs and feedback.',thesis:'A productive cycle moves from topic scan to concept map, short-answer control, long-answer comparison and final mixed revision.',points:['Week 1: Paper I-A and Paper I-B maps.','Week 2: Paper II-A and Paper II-B maps.','Week 3: timed 10- and 15-mark answers.','Week 4: mixed sectional test and error repair.'],close:'The cycle works when every attempt produces a specific revision action.'}],revision:[['Topic tag vs answer demand','The topic tells you where to begin revision; the directive tells you what intellectual operation the answer must perform.'],['Question part vs main question','Each sub-part is listed separately because it demands an independently structured answer.'],['Official wording vs study transcription','This bank improves readability; the UPSC PDF is the authority for a timed attempt.'],['Recurrence vs prediction','A repeated debate deserves deeper preparation, but no topic count guarantees a future question.']],quick:['How many answerable prompts does the 2013–2025 bank contain?','Which three fields make up a PYQ code?','What is the three-pass method for a topic?','Why can one prompt need a secondary tag?'],sources:[{name:'UPSC previous question papers',url:'https://www.upsc.gov.in/examinations/previous-question-papers',use:'authoritative yearly PSIR Paper I and Paper II PDFs; verify exact wording and marks here'},{name:'UPSC Civil Services Examination 2026 notification',url:'https://www.upsc.gov.in/sites/default/files/Notif-CSP-2026-Engl-060226Rev.pdf',use:'official PSIR syllabus and Optional-paper scheme'},{name:'UPSC 2013 examination archive',url:'https://www.upsc.gov.in/examinations/previous-question-papers',use:'official archive reference for the earliest year; readable archival scans were used only where the current listing does not expose a 2013 PSIR PDF'}],recall:['Choose one topic and name its three most recurrent question families.','Write a 90-second thesis for a 15-mark question.','Identify a question’s primary topic and one valid cross-topic bridge.','Plan the next four PYQ answers using two different papers.']});
